import { readFile } from 'node:fs/promises'
import { countCustomers } from './count.mjs'
try {
  if (!process.argv[2]) throw new Error('请提供客户 JSON 路径')
  const customers = JSON.parse(await readFile(process.argv[2], 'utf8'))
  process.stdout.write(JSON.stringify(countCustomers(customers)) + '\n')
} catch (error) {
  process.stderr.write(String(error.message) + '\n')
  process.exitCode = 1
}

